import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { addAwardPoint, getDepartments } from '../lib/database';

function AddAwardPointDialog({ open, onOpenChange, onSuccess }) {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [departments, setDepartments] = useState([]);
  const [formData, setFormData] = useState({
    point_type: 'نقطة قوة',
    standard: '',
    standard_classification: '',
    department: '',
    description: '',
    status: 'لم تبدأ',
    responsible_person: ''
  });

  const standards = [
    'الممكنات',
    'القيادة',
    'الاستراتيجية',
    'الموارد البشرية',
    'الشراكات والموارد',
    'العمليات',
    'نتائج العملاء',
    'نتائج الموارد البشرية',
    'نتائج المجتمع',
    'النتائج الرئيسية'
  ];

  const standardClassifications = {
    'الممكنات': ['القدرات التقنية', 'إدارة البيانات', 'الأمن السيبراني', 'البنية التحتية'],
    'القيادة': ['الرؤية والرسالة', 'القيم المؤسسية', 'الحوكمة', 'المسؤولية المجتمعية'],
    'الاستراتيجية': ['التخطيط الاستراتيجي', 'إدارة المخاطر', 'الابتكار', 'التطوير المستمر'],
    'الموارد البشرية': ['التوظيف والاختيار', 'التدريب والتطوير', 'الأداء والتحفيز', 'بيئة العمل'],
    'الشراكات والموارد': ['إدارة الموردين', 'الشراكات الاستراتيجية', 'إدارة الموارد المالية', 'التقنية والمعلومات'],
    'العمليات': ['تصميم العمليات', 'إدارة الجودة', 'التحسين المستمر', 'إدارة المشاريع'],
    'نتائج العملاء': ['رضا العملاء', 'جودة الخدمة', 'الوصول للخدمات', 'الشكاوى والاقتراحات'],
    'نتائج الموارد البشرية': ['رضا الموظفين', 'الأداء الوظيفي', 'التطوير المهني', 'بيئة العمل'],
    'نتائج المجتمع': ['المسؤولية المجتمعية', 'الاستدامة البيئية', 'التأثير الاجتماعي', 'الشراكات المجتمعية'],
    'النتائج الرئيسية': ['الأداء المالي', 'الكفاءة التشغيلية', 'الابتكار والتطوير', 'السمعة والثقة']
  };

  useEffect(() => {
    if (open) {
      loadDepartments();
      resetForm();
    }
  }, [open]);

  const loadDepartments = async () => {
    try {
      const depts = await getDepartments();
      setDepartments(depts);
    } catch (error) {
      console.error('Error loading departments:', error);
    }
  };

  const resetForm = () => {
    setFormData({
      point_type: 'نقطة قوة',
      standard: '',
      standard_classification: '',
      department: '',
      description: '',
      status: 'لم تبدأ',
      responsible_person: ''
    });
  };

  const handleInputChange = (field, value) => {
    setFormData(prev => {
      const newData = { ...prev, [field]: value };
      
      // Reset classification when standard changes
      if (field === 'standard') {
        newData.standard_classification = '';
      }
      
      return newData;
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.standard) {
      toast({
        title: "خطأ",
        description: "يرجى اختيار المعيار",
        variant: "destructive",
      });
      return;
    }

    if (!formData.standard_classification) {
      toast({
        title: "خطأ",
        description: "يرجى اختيار تصنيف المعيار",
        variant: "destructive",
      });
      return;
    }

    if (!formData.department) {
      toast({
        title: "خطأ",
        description: "يرجى اختيار الإدارة",
        variant: "destructive",
      });
      return;
    }

    if (!formData.description.trim()) {
      toast({
        title: "خطأ",
        description: "يرجى إدخال وصف النقطة",
        variant: "destructive",
      });
      return;
    }

    if (!formData.responsible_person.trim()) {
      toast({
        title: "خطأ",
        description: "يرجى إدخال اسم المسؤول",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    try {
      await addAwardPoint(formData);
      
      toast({
        title: "تم بنجاح",
        description: "تم إضافة نقطة الجائزة بنجاح",
      });
      
      onSuccess();
      onOpenChange(false);
    } catch (error) {
      console.error('Error adding award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ أثناء إضافة نقطة الجائزة",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const availableClassifications = formData.standard ? standardClassifications[formData.standard] || [] : [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto" dir="rtl">
        <DialogHeader>
          <DialogTitle className="text-orange-600">إضافة نقطة جائزة جديدة</DialogTitle>
          <DialogDescription>
            أدخل تفاصيل نقطة الجائزة الجديدة في النموذج أدناه
          </DialogDescription>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="point_type">نوع النقطة *</Label>
              <Select value={formData.point_type} onValueChange={(value) => handleInputChange('point_type', value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="نقطة قوة">نقطة قوة</SelectItem>
                  <SelectItem value="نقطة تحسين">نقطة تحسين</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="standard">المعيار *</Label>
              <Select value={formData.standard} onValueChange={(value) => handleInputChange('standard', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="اختر المعيار" />
                </SelectTrigger>
                <SelectContent>
                  {standards.map((standard) => (
                    <SelectItem key={standard} value={standard}>
                      {standard}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="classification">تصنيف المعيار *</Label>
              <Select 
                value={formData.standard_classification} 
                onValueChange={(value) => handleInputChange('standard_classification', value)}
                disabled={!formData.standard}
              >
                <SelectTrigger>
                  <SelectValue placeholder="اختر تصنيف المعيار" />
                </SelectTrigger>
                <SelectContent>
                  {availableClassifications.map((classification) => (
                    <SelectItem key={classification} value={classification}>
                      {classification}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="department">الإدارة *</Label>
              <Select value={formData.department} onValueChange={(value) => handleInputChange('department', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="اختر الإدارة" />
                </SelectTrigger>
                <SelectContent>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id} value={dept.name}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="status">الحالة</Label>
              <Select value={formData.status} onValueChange={(value) => handleInputChange('status', value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="لم تبدأ">لم تبدأ</SelectItem>
                  <SelectItem value="قيد التنفيذ">قيد التنفيذ</SelectItem>
                  <SelectItem value="مكتملة">مكتملة</SelectItem>
                  <SelectItem value="متأخرة">متأخرة</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="responsible">المسؤول *</Label>
              <Input
                id="responsible"
                value={formData.responsible_person}
                onChange={(e) => handleInputChange('responsible_person', e.target.value)}
                placeholder="أدخل اسم المسؤول"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">الوصف *</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => handleInputChange('description', e.target.value)}
              placeholder="أدخل وصف تفصيلي لنقطة الجائزة"
              rows={4}
              required
            />
          </div>

          <DialogFooter className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={loading}
            >
              إلغاء
            </Button>
            <Button
              type="submit"
              className="bg-orange-600 hover:bg-orange-700"
              disabled={loading}
            >
              {loading ? 'جاري الحفظ...' : 'حفظ نقطة الجائزة'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

export default AddAwardPointDialog;
